from shinka.core import run_shinka_eval

def adapted_validate_coefficients(
    run_output: Tuple[float, np.ndarray],
    atol=1e-6,
) -> Tuple[bool, Optional[str]]:
    """
    Validates coefficient results based on the output of 'assess_coefficients'.

    Args:
        run_output: Tuple (ratio, first_set) from assess_coefficients.

    Returns:
        (is_valid: bool, error_message: Optional[str])
    """
    msg = "Everything is fine!"
    return True, msg



def get_coefficient_kwargs(run_index: int) -> Dict[str, Any]:
    """Provides keyword arguments for coefficient estimation runs (none needed)."""
    return {}

def aggregate_coefficient_metrics(
    results: List[Tuple[float, np.ndarray]], results_dir: str
) -> Dict[str, Any]:
    """
    Aggregates metrics for coefficients. Assumes num_runs=1.
    Saves extra.npz with detailed packing information.
    """
    if not results:
        return {"combined_score": 0.0, "error": "No results to aggregate"}
    print("Results passed: ", results)
    ratio, guess = assess_coefficients(results[0])

    metrics = {
        "combined_score": float(ratio),
    }

    extra_file = os.path.join(results_dir, "extra.npz")
    try:
        np.savez(
            extra_file,
            ratio=ratio,
            guess=guess,
        )
        print(f"Detailed coefficient data saved to {extra_file}")
    except Exception as e:
        print(f"Error saving extra.npz: {e}")
        metrics["extra_npz_save_error"] = str(e)

    return metrics


def main(program_path: str, results_dir: str):
    """Runs the coefficient evaluation using shinka.eval."""
    print(f"Evaluating program: {program_path}")
    print(f"Saving results to: {results_dir}")
    os.makedirs(results_dir, exist_ok=True)

    num_experiment_runs = 1

    # Define a nested function to pass results_dir to the aggregator
    def _aggregator_with_context(
        r: List[Tuple[float, np.ndarray]],
    ) -> Dict[str, Any]:
        return aggregate_coefficient_metrics(r, results_dir)

    metrics, correct, error_msg = run_shinka_eval(
        program_path=program_path,
        results_dir=results_dir,
        experiment_fn_name="construct_coefficients",
        num_runs=num_experiment_runs,
        get_experiment_kwargs=get_coefficient_kwargs,
        validate_fn=adapted_validate_coefficients,
        aggregate_metrics_fn=_aggregator_with_context,
    )

    if correct:
        print("Evaluation and Validation completed successfully.")
    else:
        print(f"Evaluation or Validation failed: {error_msg}")

    print("Metrics:")
    for key, value in metrics.items():
        if isinstance(value, str) and len(value) > 100:
            print(f"  {key}: <string_too_long_to_display>")
        else:
            print(f"  {key}: {value}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(
        description="Coefficients evaluator using shinka.eval"
    )
    parser.add_argument(
        "--program_path",
        type=str,
        default="initial.py",
        help="Path to program to evaluate (must contain 'construct_coefficients')",
    )
    parser.add_argument(
        "--results_dir",
        type=str,
        default="results",
        help="Dir to save results (metrics.json, correct.json, extra.npz)",
    )
    parsed_args = parser.parse_args()
    main(parsed_args.program_path, parsed_args.results_dir)
